import {
  Plus, Search, ChevronRight, CheckCircle2, AlertCircle,
  Loader2, Activity, X, Bot, Copy, Layout, List, LogOut,
  Users, Phone, Mail, LayoutDashboard, Send, MessageCircle, Contact,
  HeartHandshake, Cake, Clock, DollarSign, BarChart3, Zap, Trash2,
  Globe, FileText, Target,
} from "lucide-react";
import { initializeApp } from "firebase/app";
import {
  getAuth, onAuthStateChanged, signInWithEmailAndPassword,
  signOut, signInAnonymously,
} from "firebase/auth";
import {
  getFirestore, collection, addDoc, updateDoc, deleteDoc,
  doc, onSnapshot, serverTimestamp,
} from "firebase/firestore";

